def score(self, x, y):
    """
    score:
    @param x: a one-dimensional numpy array (features)
    @param y: a one-dimensional numpy array (true labels)
    return value: mean squared error of predictions on given data

    Calculate the Mean Squared Error (MSE) of the model's predictions compared to the
    true labels.
    """
    predictions = np.array([self.predict(val) for val in x])
    return self.mean_squared_error(y, predictions.mean())

def train(self, x, y, validation_set=None):
    """
    train:
    @param x: a one-dimensional numpy array (features)
    @param y: a one-dimensional numpy array (labels for the corresponding x values)
    @param validation_set: a tuple (x_val, y_val) for internal validation (default: None)

    Train the decision tree and optionally evaluate on a validation set using the score method.
    """
    if x.ndim != 1:
        raise ValueError("Input data set must be one-dimensional")
    if len(x) != len(y):
        raise ValueError("x and y have different lengths")
    if y.ndim != 1:
        raise ValueError("Data set labels must be one-dimensional")

    if len(x) < 2 * self.min_leaf_size:
        self.prediction = np.mean(y)
        return

    if self.depth == 1:
        self.prediction = np.mean(y)
        return

    best_split = 0
    min_error = self.mean_squared_error(x, np.mean(y)) * 2

    for i in range(len(x)):
        if len(x[:i]) < self.min_leaf_size:
            continue
        elif len(x[i:]) < self.min_leaf_size:
            continue
        else:
            error_left = self.mean_squared_error(x[:i], np.mean(y[:i]))
            error_right = self.mean_squared_error(x[i:], np.mean(y[i:]))
            error = error_left + error_right
            if error < min_error:
                best_split = i
                min_error = error

    if best_split != 0:
        left_x = x[:best_split]
        left_y = y[:best_split]
        right_x = x[best_split:]
        right_y = y[best_split:]

        self.decision_boundary = x[best_split]
        self.left = DecisionTree(
            depth=self.depth - 1, min_leaf_size=self.min_leaf_size
        )
        self.right = DecisionTree(
            depth=self.depth - 1, min_leaf_size=self.min_leaf_size
        )
        self.left.train(left_x, left_y)
        self.right.train(right_x, right_y)
    else:
        self.prediction = np.mean(y)

    if validation_set is not None:
        x_val, y_val = validation_set
        mse_score = self.score(x_val, y_val)
        print(f"Validation MSE: {mse_score}")

    return

def get_max_depth(self):
    """
    get_max_depth:
    Calculates the maximum depth of the decision tree.
    """
    if self.left is None and self.right is None:
        return 1
    left_depth = self.left.get_max_depth() if self.left is not None else 0
    right_depth = self.right.get_max_depth() if self.right is not None else 0
    return 1 + max(left_depth, right_depth)

class DecisionTree:
    def __init__(self, depth=5, min_leaf_size=5, criterion='mse'):
        self.depth = depth
        self.decision_boundary = 0
        self.left = None
        self.right = None
        self.min_leaf_size = min_leaf_size
        self.prediction = None
        self.criterion = criterion  # can be 'mse' or 'mae'

    def mean_squared_error(self, labels, prediction):
        if labels.ndim != 1:
            print("Error: Input labels must be one dimensional")
        return np.mean((labels - prediction) ** 2)

    def mean_absolute_error(self, labels, prediction):
        if labels.ndim != 1:
            print("Error: Input labels must be one dimensional")
        return np.mean(np.abs(labels - prediction))

    def train(self, x, y):
        if x.ndim != 1:
            raise ValueError("Input data set must be one-dimensional")
        if len(x) != len(y):
            raise ValueError("x and y have different lengths")
        if y.ndim != 1:
            raise ValueError("Data set labels must be one-dimensional")

        if len(x) < 2 * self.min_leaf_size:
            self.prediction = np.mean(y)
            return

        if self.depth == 1:
            self.prediction = np.mean(y)
            return

        best_split = 0

        if self.criterion == 'mse':
            metric_fn = self.mean_squared_error
        elif self.criterion == 'mae':
            metric_fn = self.mean_absolute_error
        else:
            raise ValueError("Unsupported criterion")

        min_error = metric_fn(x, np.mean(y)) * 2

        for i in range(len(x)):
            if len(x[:i]) < self.min_leaf_size:
                continue
            elif len(x[i:]) < self.min_leaf_size:
                continue
            else:
                error_left = metric_fn(x[:i], np.mean(y[:i]))
                error_right = metric_fn(x[i:], np.mean(y[i:]))
                error = error_left + error_right
                if error < min_error:
                    best_split = i
                    min_error = error

        if best_split != 0:
            left_x = x[:best_split]
            left_y = y[:best_split]
            right_x = x[best_split:]
            right_y = y[best_split:]

            self.decision_boundary = x[best_split]
            self.left = DecisionTree(
                depth=self.depth - 1, min_leaf_size=self.min_leaf_size,
                criterion=self.criterion
            )
            self.right = DecisionTree(
                depth=self.depth - 1, min_leaf_size=self.min_leaf_size,
                criterion=self.criterion
            )
            self.left.train(left_x, left_y)
            self.right.train(right_x, right_y)
        else:
            self.prediction = np.mean(y)

        return

    def predict(self, x):
        if self.prediction is not None:
            return self.prediction
        elif self.left is not None and self.right is not None:
            if x >= self.decision_boundary:
                return self.right.predict(x)
            else:
                return self.left.predict(x)
        else:
            raise ValueError("Decision tree not yet trained")

def to_dict(self):
    """
    Returns a nested dictionary representation of the decision tree.
    Each node in the tree is represented as a dictionary with keys 'boundary',
    'prediction', 'left', and 'right'.
    - 'boundary' specifies the decision boundary at this node (or None, if leaf)
    - 'prediction' is the predicted value (or None if not leaf)
    - 'left' and 'right' are nested dictionaries for the subtrees (or None if not present)
    """
    if self.prediction is not None:
        # This is a leaf node
        return {'boundary': None, 'prediction': self.prediction, 'left': None, 'right': None}
    else:
        # This is an internal node
        return {
            'boundary': self.decision_boundary,
            'prediction': None,
            'left': self.left.to_dict() if self.left else None,
            'right': self.right.to_dict() if self.right else None
        }
